constexpr double two = 2.0;
constexpr double four = 4.0;

// Compute factorial using gamma function approximation for large values
auto factorial = [](size_t x) -> double {
    if (x == 0 || x == 1) return 1.0;
    double result = 1.0;
    for (size_t i = 2; i <= x; ++i) {
        result *= static_cast<double>(i);
    }
    return result;
};

// Compute Laguerre polynomial L_n^k(x) using recurrence relation
auto laguerre_polynomial = [](size_t n, size_t k, double x) -> double {
    if (n == 0) return 1.0;
    double prev_prev = 1.0; // L_0^k(x)
    double prev = (k + 1.0 - x) / 1.0; // L_1^k(x)

    for (size_t i = 2; i <= n; ++i) {
        double current = ((two * i + k - 1.0 - x) * prev - i * (i + k - 1.0) * prev_prev) / i;
        prev_prev = prev;
        prev = current;
    }
    return prev;
};

